# Deduplicate against existing bank using the same identity logic as backend seed.
def key(x):
    return (x.get('subject',''),x.get('source_file',''),x.get('source_page'),x.get('source_exam',''),x.get('source_year',''),x.get('question_no'),x.get('question_text','').strip())
seen={key(x) for x in data}
added=[]
for x in Q:
    k=key(x)
    if k not in seen:
        data.append(x); seen.add(k); added.append(x)
path.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print('added',len(added),'total',len(data))
from collections import Counter
print(Counter((x['source_exam'],x['source_year']) for x in added))
